'use client'

import useSWR from 'swr'
import ShiftControl from '@/components/ShiftControl'
import AdminTable from '@/components/AdminTable'
import CashSummary from '@/components/CashSummary'
import ExpenseForm from '@/components/ExpenseForm'
import ExpensesList from '@/components/ExpensesList'
import { fetcher } from '@/lib/fetcher'

export default function AdminDayPage() {
	const { data, isLoading, mutate } = useSWR('/api/admin/day', fetcher)

	if (isLoading) {
		return (
			<div className="flex items-center justify-center py-12">
				<div className="text-center">
					<div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500 mx-auto mb-4"></div>
					<p className="text-slate-600">Завантаження дня…</p>
				</div>
			</div>
		)
	}

	const shift = data?.shift

	return (
		<>
			{/* ЗАГОЛОВОК */}
			<div className="mb-8">
				<h1 className="text-4xl font-bold text-slate-900 mb-2">
					Управління днем
				</h1>
				<p className="text-slate-600">
					{new Date().toLocaleDateString('uk-UA', {
						weekday: 'long',
						year: 'numeric',
						month: 'long',
						day: 'numeric'
					})}
				</p>
			</div>

			{/* КЕРУВАННЯ ЗМІНОЮ */}
			<div className="mb-8">
				<ShiftControl onChange={mutate} />
			</div>

			{/* ⛔ ЗМІНА ЗАКРИТА */}
			{!shift && (
				<div className="bg-yellow-50 border-l-4 border-yellow-400 p-6 rounded-lg shadow-sm">
					<div className="flex items-center">
						<span className="text-3xl mr-4">⛔</span>
						<div>
							<h3 className="text-lg font-semibold text-yellow-800">Зміна закрита</h3>
							<p className="text-yellow-700 mt-1">
								Відкрий нову зміну для початку роботи
							</p>
						</div>
					</div>
				</div>
			)}

			{/* ✅ ЗМІНА ВІДКРИТА */}
			{shift && (
				<div className="space-y-8">
					{/* СТАТИСТИКА */}
					{data.summary && (
						<div className="bg-white rounded-lg shadow-sm p-6 border border-slate-200">
							<h2 className="text-xl font-bold text-slate-900 mb-4">Касса</h2>
							<CashSummary summary={data.summary} />
						</div>
					)}

					{/* ТАБЛИЦЯ ТРАНЗАКЦІЙ */}
					<div className="bg-white rounded-lg shadow-sm p-6 border border-slate-200">
						<h2 className="text-xl font-bold text-slate-900 mb-4">Транзакції</h2>
						<AdminTable 
							transactions={data?.transactions ?? []} 
							isLoading={isLoading}
						/>
					</div>

					{/* ВИТРАТИ */}
					<div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
						<div className="bg-white rounded-lg shadow-sm p-6 border border-slate-200">
							<h2 className="text-xl font-bold text-slate-900 mb-4">Додати витрати</h2>
							<ExpenseForm onAdded={mutate} />
						</div>

						<div className="bg-white rounded-lg shadow-sm p-6 border border-slate-200">
							<h2 className="text-xl font-bold text-slate-900 mb-4">Список витрат</h2>
							<ExpensesList 
								expenses={data?.expenses ?? []}
								isLoading={isLoading}
							/>
						</div>
					</div>
				</div>
			)}
		</>
	)
}